import { NextResponse } from 'next/server';
import { COMMUNITY_CODE } from '@/lib/pledges';
import { createGateToken } from '@/lib/gate-token';

export const dynamic = 'force-dynamic';

/**
 * POST /api/gate — validate the community code server-side so the actual digits
 * never appear in the client bundle. Returns { ok: true, token } on success or
 * { ok: false }.
 */
export async function POST(request) {
  let body;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ ok: false }, { status: 400 });
  }

  const provided = String(body.code ?? '').trim();
  if (provided === COMMUNITY_CODE) {
    const token = createGateToken();
    return NextResponse.json({ ok: true, token });
  }
  return NextResponse.json({ ok: false });
}

